define("quizaccess_presencial/waiting",["core/ajax"],function(Ajax){"use strict";const init=function(requestId){const region=document.querySelector('[data-region="request-status"]');if(!region){return;}const container=region.closest(".quizaccess-presencial-waiting");if(!container){return;}const renderedState=container.getAttribute("data-state");const poll=function(){Ajax.call([{methodname:"quizaccess_presencial_read_request",args:{requestid:requestId}}])[0].then(function(result){if(result.state!==renderedState){window.location.reload();return;}if(["pending","authorized","starting"].includes(result.state)){window.setTimeout(poll,5000);return;}window.location.reload();}).catch(function(){window.setTimeout(poll,5000);});};window.setTimeout(poll,5000);};return{init:init};});
